declare(strict_types=1);require_once __DIR__.'/_helper.php';konsultasi_require_access($pdo);$tapel=konsultasi_tapel($pdo);$tid=(int)($tapel['id']??0);$students=[];if($tid){$st=$pdo->prepare("SELECT s.id,s.nis,s.nisn,s.nama,mk.nama kelas FROM siswa s LEFT JOIN siswa_kelas sk ON sk.id=(SELECT sk2.id FROM siswa_kelas sk2 WHERE sk2.siswa_id=s.id AND sk2.tahun_pelajaran_id=? AND sk2.status='aktif' ORDER BY sk2.id DESC LIMIT 1) LEFT JOIN master_kelas mk ON mk.id=sk.kelas_id WHERE s.status='aktif' ORDER BY mk.urutan,mk.nama,s.nama");$st->execute([$tid]);$students=$st->fetchAll();}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();$sid=(int)($_POST['siswa_id']??0);$tanggal=trim((string)($_POST['tanggal']??date('Y-m-d')));$waktu=trim((string)($_POST['waktu']??''));$jenis=(string)($_POST['jenis']??'siswa');$topik=trim((string)($_POST['topik']??''));$per=trim((string)($_POST['permasalahan']??''));$hasil=trim((string)($_POST['hasil']??''));$kes=trim((string)($_POST['kesepakatan']??''));$tl=trim((string)($_POST['tindak_lanjut']??''));$status=(string)($_POST['status']??'baru');$ortu=isset($_POST['melibatkan_ortu'])?1:0;if(!$tid)$error='Tahun Pelajaran aktif belum tersedia.';elseif($sid<=0)$error='Siswa wajib dipilih.';elseif($topik==='')$error='Topik konsultasi wajib diisi.';elseif(!in_array($jenis,['siswa','orang_tua','wali_kelas','guru','lainnya'],true))$error='Jenis konsultasi tidak valid.';elseif(!in_array($status,['baru','proses','selesai','dibatalkan'],true))$error='Status tidak valid.';else{$ck=$pdo->prepare("SELECT COUNT(*) FROM siswa WHERE id=? AND status='aktif'");$ck->execute([$sid]);if(!(int)$ck->fetchColumn())$error='Siswa tidak ditemukan atau tidak aktif.';}if(!$error){$gid=konsultasi_guru_id($pdo);$st=$pdo->prepare("INSERT INTO konsultasi_bk(siswa_id,tahun_pelajaran_id,tanggal,waktu,jenis,topik,permasalahan,hasil,kesepakatan,tindak_lanjut,status,melibatkan_ortu,petugas_id,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)");$st->execute([$sid,$tid,$tanggal,$waktu!==''?$waktu:null,$jenis,$topik,$per!==''?$per:null,$hasil!==''?$hasil:null,$kes!==''?$kes:null,$tl!==''?$tl:null,$status,$ortu,$gid?:null,(int)($_SESSION['user_id']??0)?:null]);$id=(int)$pdo->lastInsertId();konsultasi_audit($pdo,'create',$id,'Membuat konsultasi untuk siswa ID '.$sid);header('Location: '.BASE_URL.'konsultasi/detail.php?id='.$id.'&saved=1');exit;}}
$page_title='Tambah Konsultasi';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';?><main class="main"><header class="topbar"><div class="topbar-title">Konsultasi</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content konsultasi-module"><div class="page-header"><div><h1><i class="bi bi-chat-square-text-fill"></i> Tambah Konsultasi</h1><p>Data tersimpan pada Tahun Pelajaran <?=e($tapel['nama']??'-')?>.</p></div><div style="display:flex;gap:8px;flex-wrap:wrap"><a class="btn btn-outline-primary" href="<?=BASE_URL?>siswa/qr.php" target="_blank"><i class="bi bi-qr-code-scan"></i> QR Siswa</a><a class="btn btn-secondary" href="<?=BASE_URL?>konsultasi/index.php">Kembali</a></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" class="dashboard-table-card"><?=csrf_field()?><div class="dashboard-grid" style="grid-template-columns:repeat(2,minmax(0,1fr));gap:18px"><div><label class="form-label">Siswa *</label><div class="student-picker" data-student-picker data-items="<?=e(json_encode(array_map(fn($r)=>['id'=>(int)$r['id'],'nis'=>(string)$r['nis'],'nisn'=>(string)($r['nisn']??''),'nama'=>(string)$r['nama'],'kelas'=>(string)($r['kelas']??'')],$students),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>"><input type="hidden" name="siswa_id" data-student-value value="<?=e($_POST['siswa_id']??0)?>"><div class="student-picker-toolbar"><select class="form-control" data-student-class><option value="">Pilih Kelas Terlebih Dahulu</option></select><input class="form-control" type="search" data-student-search placeholder="Cari nama/NIS/NISN..."></div><div data-student-selected></div><div class="student-picker-results" data-student-results></div><div class="student-picker-empty" data-student-empty hidden>Tidak ada siswa.</div></div><label class="form-label mt-3">Tanggal</label><input class="form-control" type="date" name="tanggal" value="<?=e($_POST['tanggal']??date('Y-m-d'))?>" required><label class="form-label mt-3">Waktu</label><input class="form-control" type="time" name="waktu" value="<?=e($_POST['waktu']??date('H:i'))?>"><label class="form-label mt-3">Jenis</label><select class="form-control" name="jenis"><?php foreach(['siswa'=>'Siswa','orang_tua'=>'Orang Tua/Wali','wali_kelas'=>'Wali Kelas','guru'=>'Guru','lainnya'=>'Lainnya'] as $v=>$l):?><option value="<?=$v?>"><?=$l?></option><?php endforeach;?></select><label class="form-label mt-3">Topik *</label><input class="form-control" name="topik" value="<?=e($_POST['topik']??'')?>" required></div><div><label class="form-label">Permasalahan/Konteks</label><textarea class="form-control" name="permasalahan" rows="5"></textarea><label class="form-label mt-3">Hasil Konsultasi</label><textarea class="form-control" name="hasil" rows="4"></textarea><label class="form-label mt-3">Kesepakatan</label><textarea class="form-control" name="kesepakatan" rows="4"></textarea><label class="form-label mt-3">Tindak Lanjut</label><textarea class="form-control" name="tindak_lanjut" rows="4"></textarea><label class="form-label mt-3">Status</label><select class="form-control" name="status"><option value="baru">Baru</option><option value="proses">Dalam Proses</option><option value="selesai">Selesai</option><option value="dibatalkan">Dibatalkan</option></select><label class="mt-3" style="display:flex;gap:8px;align-items:center"><input type="checkbox" name="melibatkan_ortu" value="1"> Melibatkan orang tua/wali</label></div></div><button class="btn btn-primary mt-3"><i class="bi bi-save"></i> Simpan Konsultasi</button></form></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
